## 2. 内存层 `Mem.h`

```cpp
#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <vector>
#include <string>
#include <initializer_list>

struct Handle {
    HANDLE h = nullptr;
    DWORD  pid = 0;
    uintptr_t base = 0;
    size_t    size = 0;
};

inline Handle g_mem;

inline DWORD FindPid(const std::wstring& exe) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe))
        do { if (exe == pe.szExeFile) { pid = pe.th32ProcessID; break; } }
        while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

inline bool Attach(const std::wstring& exe) {
    g_mem.pid = FindPid(exe);
    if (!g_mem.pid) return false;
    g_mem.h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, g_mem.pid);
    if (!g_mem.h) return false;

    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, g_mem.pid);
    MODULEENTRY32W me{ sizeof(me) };
    if (Module32FirstW(snap, &me)) {
        g_mem.base = (uintptr_t)me.modBaseAddr;
        g_mem.size = me.modBaseSize;
    }
    CloseHandle(snap);
    return g_mem.base != 0;
}

template <class T>
inline bool Read(uintptr_t addr, T& out) {
    if (!addr || !g_mem.h) return false;
    SIZE_T got = 0;
    return ReadProcessMemory(g_mem.h, (LPCVOID)addr, &out, sizeof(T), &got) && got == sizeof(T);
}

template <class T>
inline T RPM(uintptr_t addr) { T v{}; Read(addr, v); return v; }

// 多级指针链: base +{o1,+o2,+o3...} 任一跳失效返回 0
inline uintptr_t Chain(uintptr_t base, std::initializer_list<uintptr_t> offs) {
    uintptr_t p = base;
    for (auto o : offs) {
        p = RPM<uintptr_t>(p + o);
        if (p < 0x10000 || p > 0x00007FFFFFFFFFFF) return 0;
    }
    return p;
}

// 特征码: "48 8B 05 ?? ?? ?? ?? 48 85 C0" 返回首个匹配绝对地址
inline uintptr_t PatternScan(const char* sig) {
    std::vector<int> pat; std::vector<bool> mask;
    for (const char* p = sig; *p; ) {
        if (*p == ' ') { ++p; continue; }
        if (*p == '?') { pat.push_back(0); mask.push_back(false); p += (*p=='?' && p[1]=='?') ? 2 : 1; }
        else { pat.push_back((int)strtol(std::string(p,2).c_str(), nullptr, 16)); mask.push_back(true); p += 2; }
    }
    std::vector<uint8_t> buf(g_mem.size);
    SIZE_T got = 0;
    if (!ReadProcessMemory(g_mem.h, (LPCVOID)g_mem.base, buf.data(), buf.size(), &got)) return 0;

    for (size_t i = 0; i + pat.size() < got; ++i) {
        bool ok = true;
        for (size_t j = 0; j < pat.size(); ++j)
            if (mask[j] && buf[i+j] != (uint8_t)pat[j]) { ok = false; break; }
        if (ok) return g_mem.base + i;
    }
    return 0;
}

// 从 mov 指令取 RIP 相对地址 (mov rax,[rip+disp32])
inline uintptr_t ResolveRip(uintptr_t insn, int dispOffset, int insnLen) {
    int32_t disp = RPM<int32_t>(insn + dispOffset);
    return insn + insnLen + disp;
}
```

