下面整套是外部读写 + 透明覆盖层（Overlay）的透视 ESP 实现。核心就三步：拿到实体列表 → 读每个实体的坐标/血量/阵营 → 用视图矩阵做 WorldToScreen 画方框。不注入进程，全部走 `ReadProcessMemory`。

## 一、先把偏移找出来（Cheat Engine）

| 目标 | 找法 |
|---|---|
| `OFF_VIEW_MATRIX` | 视角上下左右转动时，扫描一段 16 个连续 float，值在 -1~1 和少量大数之间跳；找到后记下 `client.dll+偏移` |
| 玩家结构基址 | 搜血量（4 字节，受伤变化）→ 右键"找出是什么改写了"→ 得到基址寄存器+偏移 |
| `OFF_ENTITY_LIST` | 由本地玩家结构里存的指针往上层做"指针扫描"(Pointer Scan)，一般 2~3 级指针链，如 `client+0x1234567 → +0x10 → +0x2C8` |
| 实体步长 `OFF_ENTITY_SIZE` | 实体列表里相邻两个有效实体的地址差，常见 0x78 / 0x1A8 / 0x4E0 |
| 血量/阵营/坐标 | 在实体结构内逐个 diff，坐标是 3 个连续 float，走动时 x/z 变化明显，y 变化小 |

指针链一定用 `ResolveChain` 逐级解引用，别直接当绝对地址用。

## 二、完整代码

```cpp
// esp.cpp  —— MSVC x64 编译：cl /std:c++17 /O2 esp.cpp user32.lib gdi32.lib
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <TlHelp32.h>
#include <cstdio>
#include <cmath>
#include <vector>
#include <string>
#include <initializer_list>

// ================= 配置区：CE 找到后填这里 =================
static const wchar_t* PROC_NAME   = L"Game.exe";
static const wchar_t* MODULE_NAME = L"client.dll";      // 主模块或 client.dll

static const uintptr_t CHAIN_ENTITY_LIST[] = { 0x0 };   // 例：{0x1A2B3C4, 0x10, 0x2C8}
static const uintptr_t CHAIN_VIEW_MATRIX[] = { 0x0 };   // 例：{0x2D4F1A0}
static const uintptr_t CHAIN_LOCAL_PLAYER[]= { 0x0 };

static const uintptr_t OFF_ENTITY_SIZE = 0x78;   // 实体步长
static const uintptr_t OFF_HEALTH       = 0x100; // 血量 int
static const uintptr_t OFF_TEAM         = 0x104; // 阵营 int
static const uintptr_t OFF_POS          = 0x138; // 原点 Vec3 (x,y,z)
static const int       MAX_ENTITIES     = 64;

static const int SW = 1920, SH = 1080;           // 游戏分辨率
static const COLORREF KEY_COLOR = RGB(1,1,1);    // 抠色键，绘制时避开此色
// =========================================================

struct Vec3 { float x, y, z; };
struct Vec2 { float x, y; };
struct Matrix4x4 { float m[4][4]; };

// ---------------- 内存读写封装 ----------------
class Mem {
public:
    HANDLE    h    = nullptr;
    DWORD     pid  = 0;
    uintptr_t base = 0;

    bool Attach(const wchar_t* proc, const wchar_t* mod) {
        pid = FindPid(proc);
        if (!pid) return false;
        // 只要读权限，别开 PROCESS_VM_WRITE / PROCESS_ALL_ACCESS
        h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!h) return false;
        base = ModuleBase(pid, mod);
        return base != 0;
    }

    template <typename T>
    bool Read(uintptr_t addr, T& out) const {
        SIZE_T got = 0;
        return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), &got) && got == sizeof(T);
    }

    template <typename T>
    T Read(uintptr_t addr, T def = T{}) const {
        T v{}; return Read(addr, v) ? v : def;
    }

    uintptr_t Chain(uintptr_t root, const uintptr_t* offs, size_t n) const {
        uintptr_t p = root;
        for (size_t i = 0; i < n; ++i) {
            p = Read<uintptr_t>(p + offs[i], 0);
            if (!p) return 0;
        }
        return p;
    }

private:
    static DWORD FindPid(const wchar_t* name) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return 0;
        PROCESSENTRY32W pe{ sizeof(pe) };
        DWORD result = 0;
        if (Process32FirstW(snap, &pe)) {
            do {
                if (!_wcsicmp(pe.szExeFile, name)) { result = pe.th32ProcessID; break; }
            } while (Process32NextW(snap, &pe));
        }
        CloseHandle(snap);
        return result;
    }

    static uintptr_t ModuleBase(DWORD pid, const wchar_t* mod) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        if (snap == INVALID_HANDLE_VALUE) return 0;
        MODULEENTRY32W me{ sizeof(me) };
        uintptr_t result = 0;
        if (Module32FirstW(snap, &me)) {
            do {
                if (!_wcsicmp(me.szModule, mod)) { result = (uintptr_t)me.modBaseAddr; break; }
            } while (Module32NextW(snap, &me));
        }
        CloseHandle(snap);
        return result;
    }
};

// ---------------- WorldToScreen ----------------
static bool WorldToScreen(const Vec3& p, Vec2& out, const Matrix4x4& v, int sw, int sh) {
    float w = v.m[3][0]*p.x + v.m[3][1]*p.y + v.m[3][2]*p.z + v.m[3][3];
    if (w < 0.01f) return false;                     // 在身后
    float x = v.m[0][0]*p.x + v.m[0][1]*p.y + v.m[0][2]*p.z + v.m[0][3];
    float y = v.m[1][0]*p.x + v.m[1][1]*p.y + v.m[1][2]*p.z + v.m[1][3];
    out.x = (sw * 0.5f) + (sw * 0.5f) * x / w;
    out.y = (sh * 0.5f) - (sh * 0.5f) * y / w;
    return true;
}

static float Dist(const Vec3& a, const Vec3& b) {
    float dx = a.x-b.x, dy = a.y-b.y, dz = a.z-b.z;
    return std::sqrt(dx*dx + dy*dy + dz*dz);
}

// ---------------- 实体扫描 ----------------
struct Box { Vec2 top, bot; bool valid; };

static Mem g_mem;
static Matrix4x4 g_view{};
static Vec3 g_localPos{};
static int  g_localTeam = 0;
static std::vector<Box> g_boxes;
static std::vector<std::wstring> g_labels;
static std::vector<Vec2> g_heads;

static void ScanEntities() {
    g_boxes.clear(); g_labels.clear(); g_heads.clear();
    if (!g_mem.h) return;

    // 视图矩阵
    uintptr_t vmAddr = 0;
    if (sizeof(CHAIN_VIEW_MATRIX)/sizeof(uintptr_t) == 0) return;
    if (CHAIN_VIEW_MATRIX[0] == 0) return;           // 未填写 = 不跑
    vmAddr = g_mem.Chain(g_mem.base, CHAIN_VIEW_MATRIX,
                         sizeof(CHAIN_VIEW_MATRIX)/sizeof(uintptr_t));
    if (!vmAddr || !g_mem.Read(vmAddr, g_view)) return;

    // 实体数组头（两种布局都兼容）
    uintptr_t listAddr = (CHAIN_ENTITY_LIST[0] == 0)
                       ? 0
                       : g_mem.Chain(g_mem.base, CHAIN_ENTITY_LIST,
                                     sizeof(CHAIN_ENTITY_LIST)/sizeof(uintptr_t));
    if (!listAddr) return;

    // 本地玩家
    uintptr_t local = (CHAIN_LOCAL_PLAYER[0] == 0) ? 0
                    : g_mem.Chain(g_mem.base, CHAIN_LOCAL_PLAYER,
                                  sizeof(CHAIN_LOCAL_PLAYER)/sizeof(uintptr_t));
    if (local) {
        g_mem.Read(local + OFF_POS, g_localPos);
        g_mem.Read(local + OFF_TEAM, g_localTeam);
    }

    for (int i = 0; i < MAX_ENTITIES; ++i) {
        // 布局 A：指针数组  listAddr + i*8   -> 实体指针
        // 布局 B：结构数组  listAddr + i*OFF_ENTITY_SIZE
        uintptr_t ent = g_mem.Read<uintptr_t>(listAddr + i * 8, 0);
        if (ent < 0x10000 || ent > 0x7FFFFFFF0000ull)
            ent = listAddr + i * OFF_ENTITY_SIZE;

        int health = g_mem.Read
